effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:
 //////////////////////////
 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     // const int ITERATIONS = 5;
     // const float SPEED = 0.25;
     // const float PAN = 2.8;
     // const float MASK_VIS = 0.0; // Set between 0-1 to visualize masks

     float vortex(vec2 uv, float dist, float seed, float bias, float offset)
     {
         float ang = atan(uv.y, uv.x)+sin(dist+0.1*seed)*(1.2-offset)*2.0;
         ang += 3.14159*(0.01*seed);
         return clamp((sin((ang)*(3.0+offset*float(ITERATIONS)))+bias)/(1.0+bias), 0.0, 1.0);
     }
 //////////////////////////
     void main() {
     if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);

     vec2 TanRyu;
     TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     TanRyu.y*=acLayerSize.y/acLayerSize.x;
     TanRyu /= scale;
     TanRyu *= rot2m((0.0+angle)*0.0174533);
     TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     TanRyu /= scaleVec;

     /////////////////////////

 	vec4 fragColor;
 	const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);

         vec2 uv = TanRyu;
         float texel = 1.0/iResolution.y;
         float dist = length(uv);
         vec3 col = vec3(0.0);
         for (int i=0; i<int(ITERATIONS); i++) 
         {
             float offset = float(i)/float(ITERATIONS);
             float seed = 1000.0*fract(3.1379136*floor(SEEDX*SPEED+offset));
             float time = fract(PROGRESS*SPEED+offset);
             vec2 pan = vec2(0.0, time*PAN);
             float maskA = vortex(uv, dist, seed+100.0*float(i), -0.998+texel, offset);
             float dist2 = length(uv+pan);
             float maskB = vortex(uv+pan, dist2, seed+42.0*float(i), -0.99+texel, offset);
             float radius = pow(((maskA*maskA)+(maskB*maskB)), 2.0);
             float fade = time*(1.0-time);
             float mask = maskA*maskB*fade*radius;
             // col = mix(vec3(0.,0.,0.),vec3(1.,1.,1.), mask);
             col = mix(col, vec3(1.0+1.0*dist-0.2*offset-0.1*radius, 1.0-0.5*offset-0.5*dist, 1.0-0.8*dist), mask);
             col = max(vec3(maskA*MASK_VIS, maskB*MASK_VIS+0.1, max(maskA*MASK_VIS*2.0, maskB*MASK_VIS)+0.12)*fade, col);
         }
         fragColor = vec4(col*4.0,1.0);

 	// vec4 factor = mix(texColorX,fragColor,1.0);
 	// if(GMAP) { 
         vec4 gradmap;
         float luminance = dot(fragColor.rgb, luminanceWeighting);
         gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    vec4 factor = mix(texColorX,gradmap,1.0);

     vec4 resultfinal;
       if( blendMode==0 ) {
         resultfinal = (factor * hardness) * texColor.a; }
         // resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; 
         resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
       }
     }
